INSERT INTO stages (slug, name, tagline, description, badge_soft, badge_solid, icon, highlights, sort_order) VALUES ('after-10th', 'After 10th', 'Choose your stream, or a skill-first path', 'The first big fork in the road: pick a stream for 11th & 12th, or move straight into a diploma, ITI or skill-led path toward a hands-on career.', 'bg-stage-10th-soft text-stage-10th', 'bg-stage-10th text-white', 'cap', ARRAY['Choose Stream (Science / Commerce / Arts)','Diploma / ITI','Skill Courses','Junior-level Career Options'], 0);
INSERT INTO stages (slug, name, tagline, description, badge_soft, badge_solid, icon, highlights, sort_order) VALUES ('after-12th', 'After 12th', 'Pick your degree, diploma or entrance exam path', 'With a stream behind you, this is where career direction sharpens — undergraduate degrees, professional courses, and the entrance exams that unlock them.', 'bg-stage-12th-soft text-stage-12th', 'bg-stage-12th text-white', 'book', ARRAY['Science / Commerce / Arts & Humanities','Professional & Vocational Courses','Diploma Options','Entrance Exams'], 1);
INSERT INTO stages (slug, name, tagline, description, badge_soft, badge_solid, icon, highlights, sort_order) VALUES ('graduation', 'After Graduation', 'Specialize, go for higher studies, or start working', 'A bachelor''s degree opens three roads at once: postgraduate study, competitive government exams, or stepping directly into a first job.', 'bg-stage-grad-soft text-stage-grad', 'bg-stage-grad text-white', 'trophy', ARRAY['Higher Studies (MBA / MCA / M.Tech)','Government Exams','Professional Certifications','Jobs & Competitive Exams'], 2);
INSERT INTO stages (slug, name, tagline, description, badge_soft, badge_solid, icon, highlights, sort_order) VALUES ('post-graduation', 'Post-Graduation', 'Go deep: research, academia or specialized industry roles', 'For those who want to specialize further — through a Ph.D., a teaching qualification, or a postgraduate entrance into judiciary or research careers.', 'bg-stage-pg-soft text-stage-pg', 'bg-stage-pg text-white', 'flask', ARRAY['PhD & Research','Specialized Certifications','Teaching / Academia','Government & Industry Careers'], 3);
INSERT INTO stages (slug, name, tagline, description, badge_soft, badge_solid, icon, highlights, sort_order) VALUES ('working-professional', 'Working Professional', 'Upskill, grow, or move into a bigger role', 'Already working? This is about deliberate growth — new certifications, salary progression, and moving into leadership or specialist tracks.', 'bg-stage-work-soft text-stage-work', 'bg-stage-work text-white', 'brief', ARRAY['Upskilling & Certifications','Salary Improvement','Job Switch','Leadership Growth'], 4);
INSERT INTO stages (slug, name, tagline, description, badge_soft, badge_solid, icon, highlights, sort_order) VALUES ('career-switch', 'Career Switch', 'Change direction with a plan, not a guess', 'Switching careers doesn''t mean starting over. Assess your transferable skills, find the right bridge course, and move into a new field with a clear roadmap.', 'bg-stage-switch-soft text-stage-switch', 'bg-stage-switch text-white', 'switch', ARRAY['Career Assessment','Transferable Skills','New Courses & Industries','Personalized Roadmap'], 5);
